import org.apache.commons.cli.Option;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class Option_GetValueTest {

    // Helper to replace the private 'values' field via reflection
    private void setOptionValues(Option opt, String... vals) throws Exception {
        Field valuesField = Option.class.getDeclaredField("values");
        valuesField.setAccessible(true);
        List<String> newValues = new ArrayList<>();
        for (String v : vals) {
            newValues.add(v);
        }
        valuesField.set(opt, newValues);
    }

    @Test
    void returnsDefaultWhenNoValuesPresent() throws Exception {
        Option option = new Option("a", "some description");
        // no values set -> expect default returned
        assertEquals("default", option.getValue("default"));
        // also verify null default yields null when no values
        assertNull(option.getValue(null));
    }

    @Test
    void returnsFirstValueWhenValuesPresent() throws Exception {
        Option option = new Option("b", "some description");
        setOptionValues(option, "first", "second");
        // first value should be returned, ignoring provided default
        assertEquals("first", option.getValue("ignoredDefault"));
    }

    @Test
    void returnsEmptyStringIfFirstValueIsEmptyString() throws Exception {
        Option option = new Option("c", "some description");
        setOptionValues(option, "");
        // empty string is a non-null value and should be returned (not the default)
        assertEquals("", option.getValue("theDefault"));
    }

    @Test
    void worksWhenHasArgConstructorUsedAndNoValues() throws Exception {
        // use constructor with hasArg true to ensure no side-effects on getValue(String)
        Option option = new Option("d", null, true, "desc");
        // even when hasArg was set at construction, absence of values should return the default
        assertEquals("fallback", option.getValue("fallback"));
    }
}

